(() => {
function initFooter() {
const footer = document.querySelector('#footer');
if (!footer) return;
const brand = footer.querySelector('.bema-footer-brand');
const host = brand?.closest('.custom-footer');
if (brand && host && !host.querySelector('.bema-footer-grid')) {
const columns = [...host.querySelectorAll('.bema-footer-column')];
if (columns.length === 5) {
const native = footer.querySelector('.site-name');
const originalParent = native?.parentElement;
if (native && !brand.contains(native)) {
const link = native.querySelector('a');
if (link) {
brand.querySelector('.bema-footer-logo')?.remove();
link.classList.add('bema-footer-logo');
const image = link.querySelector('img');
if (image) image.alt = 'BEMA';
brand.prepend(link);
native.remove();
if (originalParent && originalParent !== host && originalParent !== footer &&
!originalParent.textContent.trim() && !originalParent.querySelector('img,a,button,input,form,.bema-footer-column')) {
originalParent.classList.add('bema-footer-logo-source');
}
}
}
const grid = document.createElement('div');
grid.className = 'bema-footer-grid';
host.prepend(grid);
grid.append(...columns);
host.classList.add('bema-footer-ready');
}
}
const signature = document.getElementById('signature');
if (!signature || signature.querySelector('.bema-footer-credit, .AdatelierSignature')) return;
const link = document.createElement('a');
link.href = 'https://adatelier.sk/';
link.className = 'bema-footer-credit';
link.append('a ');
const image = document.createElement('img');
image.src = 'https://adatelier.sk/wp-content/uploads/2025/06/Adatelier-white-logo.png';
image.width = 25;
image.height = 25;
image.alt = '';
image.loading = 'lazy';
image.decoding = 'async';
link.append(image, ' Adatelier');
signature.appendChild(link);
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initFooter, { once: true });
else initFooter();
})();
/* QuickFinder: lazy, same-origin XML, no external libraries */
(() => {
  const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
  const val = (node, names) => { for (const n of names) { const e = node.querySelector(n); if(e?.textContent.trim()) return e.textContent.trim(); } return ''; };
  const kinds = [['lahve','Lahve'],['dozy','Dózy a kelímky'],['kanystry','Kanystry'],['kbeliky','Kbelíky']];
  const ranges = [['0-100','do 100 ml',0,100],['100-500','100–500 ml',100,500],['500-1500','500 ml – 1,5 l',500,1500],['1500-5000','1,5–5 l',1500,5000],['5000+','nad 5 l',5000,Infinity]];
  const volume = s => { const m = norm(s).match(/^(\d+(?:[.,]\d+)?)\s*(ml|cl|dl|l)?$/); return m ? Number(m[1].replace(',','.')) * ({ml:1,cl:10,dl:100,l:1000}[m[2]] || 1) : null; };
  function safeURL(s, image=false) {
    if(!s) return '';
    try { const u=new URL(s,location.origin); return /^https?:$/.test(u.protocol) && (image || u.origin===location.origin) ? u.href : ''; } catch { return ''; }
  }
  function parse(xml) {
    const doc=new DOMParser().parseFromString(xml,'application/xml');
    if(doc.querySelector('parsererror')) throw Error('Neplatné XML');
    return [...doc.querySelectorAll('SHOPITEM')].map(item=>{
      const params=new Map();
      for(const p of item.querySelectorAll('PARAM, PARAMETER, FILTER_PARAMETER, TEXT_PROPERTY, PROPERTY')) {
        const key=norm(val(p,['PARAM_NAME','NAME','TITLE','PARAMETER_NAME']));
        const value=val(p,['VAL','VALUE','PARAM_VALUE','PARAMETER_VALUE']);
        if(key && value) params.set(key,[...(params.get(key)||[]),value]);
      }
      const param=(re)=>[...params].filter(([k])=>re.test(k)).flatMap(([,v])=>v);
      const name=val(item,['PRODUCTNAME','PRODUCT','NAME']);
      const cat=[...item.querySelectorAll('CATEGORYTEXT,CATEGORY')].map(n=>n.textContent).join(' ');
      const key=norm(cat+' '+name);
      const kind=/kanystr/.test(key)?'kanystry':/kbelik/.test(key)?'kbeliky':/doz|kelim/.test(key)?'dozy':/lahv|lahev|lahvick/.test(key)?'lahve':'';
      const direct=(names)=>val(item,names);
      const materials=param(/material|plast/);
      if(!materials.length) { const match=norm(name).match(/\b(pet|hdpe|ldpe|pp|pe)\b/); if(match) materials.push(match[1].toUpperCase()); }
      const volumes=param(/objem|kapacit/);
      const neck=param(/hrdlo|zavit/),sector=param(/odvetvi|pouziti|oblast/);
      return { name,kind,materials:materials.map(s=>s.trim().toUpperCase()),volume:volume(volumes[0]||''),neck,sector,code:direct(['CODE','ITEM_ID','PRODUCT_ID']),url:safeURL(direct(['URL','PRODUCT_URL'])),image:safeURL(direct(['IMGURL','IMAGE_URL','IMAGE']),true) };
    }).filter(p=>p.name && p.url && p.kind);
  }
  function init(root) {
    if(root.dataset.bemaReady) return;
    root.dataset.bemaReady='true';
    const q=s=>root.querySelector(s);
    const options=k=>q('[data-bema-options="'+k+'"]');
    const message=q('[data-bema-message]'),list=q('.bema-finder-results'),count=q('[data-bema-count]'),show=q('[data-bema-show]');
    const state={kind:'lahve',materials:new Set(),volume:'',neck:'',sector:''};
    let products=[],ready=false,expanded=false;
    const uniq=xs=>[...new Set(xs)].filter(Boolean).sort((a,b)=>a.localeCompare(b,'cs'));
    const pool=()=>products.filter(p=>p.kind===state.kind);
    const matches=(p,omit='')=> (omit==='material'||!state.materials.size||p.materials.some(m=>state.materials.has(m))) && (omit==='volume'||!state.volume||ranges.some(([id,,lo,hi])=>id===state.volume&&p.volume!==null&&p.volume>=lo&&p.volume<hi)) && (omit==='neck'||!state.neck||p.neck.includes(state.neck)) && (omit==='sector'||!state.sector||p.sector.includes(state.sector));
    function chips(key,items,selected,handler) {
      const host=options(key); host.replaceChildren();
      for(const [id,label,n] of items) { const b=document.createElement('button'); b.type='button'; b.textContent=label+(n===undefined?'':' ('+n+')'); b.setAttribute('aria-pressed',String(selected(id))); b.addEventListener('click',()=>{handler(id);expanded=false;render();}); host.append(b); }
    }
    function select(key,values) {
      const el=q('[data-bema-field="'+key+'"]'); el.replaceChildren(new Option('Libovolné',''));
      for(const v of values) el.add(new Option(v,v));
      el.value=state[key]; if(el.value!==state[key]) state[key]='';
      el.disabled=!values.length;
    }
    function render() {
      const ps=pool();
      chips('kind',kinds,id=>state.kind===id,id=>{state.kind=id;state.materials.clear();state.volume='';state.neck='';state.sector='';});
      chips('material',uniq(ps.flatMap(p=>p.materials)).map(v=>[v,v,ps.filter(p=>matches(p,'material')&&p.materials.includes(v)).length]),v=>state.materials.has(v),v=>state.materials.has(v)?state.materials.delete(v):state.materials.add(v));
      chips('volume',ranges.map(([id,label,lo,hi])=>[id,label,ps.filter(p=>matches(p,'volume')&&p.volume!==null&&p.volume>=lo&&p.volume<hi).length]),id=>state.volume===id,id=>state.volume=state.volume===id?'':id);
      select('neck',uniq(ps.flatMap(p=>p.neck)));select('sector',uniq(ps.flatMap(p=>p.sector)));
      const results=ps.filter(p=>matches(p));
      list.replaceChildren();
      for(const p of results.slice(0,expanded?100:4)) {
        const li=document.createElement('li'),a=document.createElement('a'),text=document.createElement('span');
        a.href=p.url; if(p.image){const img=document.createElement('img');img.src=p.image;img.alt='';img.width=64;img.height=64;img.loading='lazy';a.append(img);}
        text.textContent=p.name;if(p.code){const small=document.createElement('small');small.textContent=p.code;text.append(small);} a.append(text);li.append(a);list.append(li);
      }
      count.textContent=ready?String(results.length):'–';show.disabled=!ready||results.length<=4||expanded;
      show.textContent=expanded?'Zobrazené produkty':'Zobrazit produkty ('+results.length+')';
      message.textContent=!ready?'Načítání produktů…':!results.length?'Takovou kombinaci nemáme. Zkuste jiné parametry.':results.length>(expanded?100:4)?'a ještě '+(results.length-(expanded?100:4))+' produktů':'';
    }
    for(const k of ['neck','sector']) q('[data-bema-field="'+k+'"]').addEventListener('change',e=>{state[k]=e.target.value;expanded=false;render();});
    q('.bema-finder-reset').addEventListener('click',()=>{state.materials.clear();state.volume='';state.neck='';state.sector='';expanded=false;render();});
    show.addEventListener('click',()=>{expanded=true;render();});
    render();
    async function load() {
      try {
        const url=new URL(root.dataset.feed,location.origin);
        if(url.origin!==location.origin||!root.dataset.feed||root.dataset.feed.includes('REPLACE_'))throw Error('Feed není nastaven');
        const response=await fetch(url,{credentials:'same-origin',cache:'default'});
        if(!response.ok)throw Error('HTTP '+response.status);
        products=parse(await response.text());if(!products.length)throw Error('XML neobsahuje rozpoznané produkty');
        ready=true;render();
      } catch(e) { message.textContent='Produkty se nepodařilo načíst. Zkuste prosím později.';console.warn('[BEMA finder]',e.message); }
    }
    if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){observer.disconnect();load();}},{rootMargin:'300px'});observer.observe(root);}else load();
  }
  const start=()=>document.querySelectorAll('.bema-finder').forEach(init);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();


/* Bestseller carousel: preserve native product nodes and cart forms */
(() => {
  function init() {
    if(!document.body.classList.contains('in-index')) return;
    const track=document.getElementById('products-1'), heading=document.querySelector('.homepage-products-heading-1');
    if(!track||!heading||track.classList.contains('bema-bestseller-track')) return;
    const cards=[...track.children].filter(el=>el.classList.contains('product'));
    if(!cards.length) return;
    const make=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text)el.textContent=text;return el;};
    const svg=(path)=>{const el=document.createElementNS('http://www.w3.org/2000/svg','svg');el.setAttribute('viewBox','0 0 24 24');el.setAttribute('width','20');el.setAttribute('height','20');el.setAttribute('fill','none');el.setAttribute('stroke','currentColor');el.setAttribute('stroke-width','1.8');el.setAttribute('stroke-linecap','round');el.setAttribute('stroke-linejoin','round');el.setAttribute('aria-hidden','true');const p=document.createElementNS(el.namespaceURI,'path');p.setAttribute('d',path);el.append(p);return el;};
    const head=make('div','bema-bestseller-head'),copy=make('div'),controls=make('div','bema-bestseller-controls');
    heading.before(head);heading.setAttribute('role','heading');heading.setAttribute('aria-level','2');heading.id=heading.id||'bema-bestseller-title';copy.append(heading);
    const lead=make('p','','Vyberte si z nejčastěji objednávaných produktů.');copy.append(lead);
    const prev=make('button'),next=make('button');for(const [b,label,path] of [[prev,'Předchozí','M15 6l-6 6 6 6'],[next,'Další','M9 6l6 6-6 6']]){b.type='button';b.setAttribute('aria-label',label);b.setAttribute('aria-controls',track.id);b.append(svg(path));}
    controls.append(prev,next);head.append(copy,controls);
    const progress=make('div','bema-bestseller-progress'),thumb=make('span');progress.setAttribute('aria-hidden','true');progress.append(thumb);track.after(progress);
    track.classList.add('bema-bestseller-track');track.tabIndex=0;track.setAttribute('role','region');track.setAttribute('aria-labelledby',heading.id);
    for(const card of cards){const code=card.querySelector('.p-code'),name=card.querySelector('.name'),button=card.querySelector('button.btn-cart');if(code&&name)name.after(code);if(button){button.append(svg('M5 8h14l1 13H4L5 8z M9 9V6a3 3 0 0 1 6 0v3'));button.classList.add('bema-bag-ready');}}
    let raf=0;function measure(){raf=0;const max=track.scrollWidth-track.clientWidth;prev.disabled=track.scrollLeft<=2;next.disabled=track.scrollLeft>=max-2;progress.style.visibility=max<=2?'hidden':'visible';const ratio=Math.min(1,track.clientWidth/Math.max(1,track.scrollWidth));thumb.style.width=ratio*100+'%';thumb.style.transform='translateX('+(max>0?Math.max(0,Math.min(1,track.scrollLeft/max))*(1-ratio)/ratio*100:0)+'%)';}
    function schedule(){if(!raf)raf=requestAnimationFrame(measure);}
    function step(dir){const gap=parseFloat(getComputedStyle(track).columnGap)||0;track.scrollBy({left:dir*(cards[0].getBoundingClientRect().width+gap),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
    prev.addEventListener('click',()=>step(-1));next.addEventListener('click',()=>step(1));track.addEventListener('scroll',schedule,{passive:true});if('ResizeObserver' in window)new ResizeObserver(schedule).observe(track);else window.addEventListener('resize',schedule);
    let drag=null,suppress=false;
    track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('button,input,select,textarea,form'))return;drag={id:e.pointerId,x:e.clientX,left:track.scrollLeft,active:false};});
    track.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x;if(!drag.active&&Math.abs(dx)<5)return;if(!drag.active){drag.active=true;track.classList.add('bema-dragging');try{track.setPointerCapture(e.pointerId);}catch{}}track.scrollLeft=drag.left-dx;});
    const end=()=>{if(!drag)return;if(drag.active){suppress=true;track.classList.remove('bema-dragging');setTimeout(()=>{suppress=false;},0);}drag=null;};
    track.addEventListener('pointerup',end);track.addEventListener('pointercancel',end);track.addEventListener('lostpointercapture',end);track.addEventListener('pointerleave',()=>{if(drag&&!drag.active)drag=null;});
    track.addEventListener('dragstart',e=>e.preventDefault());track.addEventListener('click',e=>{if(suppress){e.preventDefault();e.stopImmediatePropagation();}},true);schedule();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();

/* EcoFilm + Ticker: original behavior, lazy video */
(() => {
  function init(root) {
    if (root.dataset.bemaEcoReady) return;
    const film=root.querySelector('.bema-eco-film'),v=film?.querySelector('video'),btn=film?.querySelector('button');
    if(!v||!btn)return;
    root.dataset.bemaEcoReady='true';
    const motion=matchMedia('(prefers-reduced-motion: reduce)');
    const auto=()=>!motion.matches&&!navigator.connection?.saveData;
    let visible=false,userPaused=false,manual=false,failed=false;
    const sync=()=>{btn.setAttribute('aria-pressed',String(!v.paused));btn.setAttribute('aria-label',v.paused?'Přehrát video':'Pozastavit video');};
    const play=()=>{if(failed)return;if(!v.getAttribute('src'))v.src=v.dataset.src;v.play().catch(()=>sync());};
    const update=()=>{if(document.hidden||!visible||userPaused||(!auto()&&!manual))v.pause();else play();};
    v.muted=true;btn.hidden=false;
    v.addEventListener('play',sync);v.addEventListener('pause',sync);
    v.addEventListener('playing',()=>film.classList.add('bema-film-shown'));
    v.addEventListener('error',()=>{failed=true;btn.hidden=true;film.classList.remove('bema-film-shown');});
    btn.addEventListener('click',()=>{if(v.paused){userPaused=false;manual=true;play();}else{userPaused=true;manual=false;v.pause();}});
    if('IntersectionObserver' in window){new IntersectionObserver(([e])=>{visible=e.isIntersecting&&e.intersectionRatio>=.5;update();},{threshold:[0,.5]}).observe(film);}
    document.addEventListener('visibilitychange',update);
    motion.addEventListener?.('change',()=>{manual=false;update();});
    navigator.connection?.addEventListener?.('change',()=>{manual=false;update();});
    if(!('IntersectionObserver' in window)||motion.matches)return;
    const format={rpet:p=>'až −'+Math.round(70*p)+'\u00a0%',light:p=>Math.round(20*p)+'–'+Math.round(30*p)+'\u00a0%',pallet:p=>(96.9*p).toFixed(1).replace('.',',')+'\u00a0%'};
    const observer=new IntersectionObserver(entries=>{for(const e of entries){if(!e.isIntersecting||e.intersectionRatio<.5)continue;observer.unobserve(e.target);const el=e.target,final=el.textContent,render=format[el.dataset.bemaTicker];if(!render||motion.matches)continue;const start=performance.now();function tick(now){const t=Math.min(1,(now-start)/1100);el.textContent=t===1||motion.matches?final:render(1-Math.pow(1-t,4));if(t<1&&!motion.matches)requestAnimationFrame(tick);}requestAnimationFrame(tick);}},{threshold:.5});
    root.querySelectorAll('[data-bema-ticker]').forEach(el=>observer.observe(el));
  }
  const start=()=>document.querySelectorAll('.in-index .bema-eco').forEach(init);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();

/* PrintSlab: local text preview, no external dependencies */
(() => {
  const palette={white:['#fff','#0d1014'],black:['#0d1014','#fff'],red:['#dc0612','#fff']};
  function init(root) {
    if(root.dataset.bemaPrintReady)return;
    const input=root.querySelector('.bema-print-input input'),box=root.querySelector('.bema-print-label'),label=root.querySelector('.bema-print-label-text'),probe=root.querySelector('.bema-print-probe'),zone=root.querySelector('.bema-print-label-zone');
    if(!input||!box||!label||!probe||!zone)return;
    root.dataset.bemaPrintReady='true';
    function fit(){
      const value=input.value.trim()||'Vaše značka';
      label.textContent=value;label.classList.toggle('bema-print-ghost',!input.value.trim());
      const width=box.clientWidth;if(!width)return;
      probe.textContent=value;const whole=probe.getBoundingClientRect().width;
      if(!whole)return;
      const size=100*width*.78/whole;
      if(size>=14){label.style.fontSize=Math.min(40,size)+'px';label.style.whiteSpace='nowrap';label.style.overflowWrap='normal';}
      else {probe.textContent=value.split(/\s+/).reduce((a,b)=>a.length>b.length?a:b,'');const word=probe.getBoundingClientRect().width;label.style.fontSize=Math.max(10,Math.min(14,100*width*.9/Math.max(1,word)))+'px';label.style.whiteSpace='normal';label.style.overflowWrap='anywhere';}
    }
    input.addEventListener('input',fit);
    const buttons=[...root.querySelectorAll('.bema-print-swatches button')];
    for(const b of buttons)b.addEventListener('click',()=>{const color=b.dataset.color;if(!palette[color])return;const [bg,fg]=palette[color];zone.setAttribute('fill',bg);zone.setAttribute('stroke',color==='black'?'rgb(255 255 255 / 32%)':'none');box.style.color=fg;buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
    if('ResizeObserver'in window)new ResizeObserver(fit).observe(box);
    document.fonts?.ready.then(fit);fit();
  }
  const start=()=>document.querySelectorAll('.in-index .bema-print').forEach(init);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();

/* B2B import demonstration: no uploads or cart mutations */
(() => {
  function init(root) {
    if(root.dataset.bemaB2bReady)return;
    const demo=root.querySelector('.bema-b2b-demo'), replay=root.querySelector('.bema-b2b-replay');
    if(!demo||!replay)return;
    root.dataset.bemaB2bReady='true';
    const rows=[...demo.querySelectorAll('[data-on]')],steps=[...root.querySelectorAll('.bema-b2b-steps li')],motion=matchMedia('(prefers-reduced-motion: reduce)');
    let timers=[];
    function stage(s){demo.dataset.stage=s;const n=s==='idle'?0:s==='drop'?1:2;steps.forEach((e,i)=>i===n?e.setAttribute('aria-current','step'):e.removeAttribute('aria-current'));demo.querySelector('.bema-b2b-table').setAttribute('aria-hidden',String(s==='idle'||s==='drop'));}
    function stop(){timers.forEach(clearTimeout);timers=[];stage('done');rows.forEach(e=>e.dataset.on='true');}
    function run(){stop();if(motion.matches)return;stage('idle');rows.forEach(e=>e.dataset.on='false');const later=(fn,ms)=>timers.push(setTimeout(fn,ms));later(()=>stage('drop'),300);later(()=>stage('table'),1100);rows.forEach((e,i)=>later(()=>e.dataset.on='true',1250+i*120));later(()=>stage('done'),2350);}
    replay.hidden=motion.matches;replay.addEventListener('click',run);
    root.querySelectorAll('.bema-b2b-days button').forEach(b=>b.addEventListener('click',()=>root.querySelectorAll('.bema-b2b-days button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))));
    if(!motion.matches&&'IntersectionObserver'in window){const o=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting&&e.intersectionRatio>=.5)){o.disconnect();run();}},{threshold:.5});o.observe(demo);}
    motion.addEventListener?.('change',()=>{stop();replay.hidden=motion.matches;});
  }
  const start=()=>document.querySelectorAll('.in-index .bema-b2b').forEach(init);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();

/* BEMA newsletter — preserve the original Shoptet form and all consent controls. */
(() => {
  function initNewsletter() {
    const footer=document.querySelector('#footer');
    const grid=footer?.querySelector('.bema-footer-grid');
    if(!grid||footer.querySelector('.bema-newsletter'))return;
    const forms=[...footer.querySelectorAll('form')];
    const form=forms.find(el=>/newsletter|subscribe/i.test([el.id,el.className,el.getAttribute('action')].join(' '))&&el.querySelector('input[type=email],input[name=email],input[name=newsletterEmail]'))
      ||forms.find(el=>el.closest('.newsletter,.newsletter-wrapper,.footer-newsletter,[class*="newsletter"]')&&el.querySelector('input[type=email],input[name=email],input[name=newsletterEmail]'));
    if(!form)return;
    const host=grid.parentElement;
    let source=form.closest('.custom-footer > *')||form.closest('.footer-newsletter,.newsletter-wrapper,.newsletter')||form.parentElement;
    if(!source||source===host||source.contains(grid)||source.querySelector('.bema-footer-column,.bema-footer-grid'))source=form;
    const band=document.createElement('section');band.className='bema-newsletter';band.setAttribute('aria-labelledby','bema-newsletter-title');
    const title=document.createElement('h2');title.id='bema-newsletter-title';title.textContent='Novinky a akce jednou za měsíc. K první objednávce −5\u00a0%.';
    const body=document.createElement('div');body.className='bema-newsletter-body';
    source.classList.add('bema-newsletter-native');form.classList.add('bema-newsletter-form');
    const email=form.querySelector('input[type=email],input[name=email],input[name=newsletterEmail]');email.classList.add('bema-newsletter-email');email.placeholder='vas@email.cz';email.autocomplete='email';if(!email.hasAttribute('aria-label')&&!email.labels?.length)email.setAttribute('aria-label','E-mail pro odběr novinek');
    const submit=form.querySelector('button[type=submit],input[type=submit],button:not([type])');
    if(submit){submit.classList.add('bema-newsletter-submit');if(submit.tagName==='INPUT')submit.value='Odebírat';else{submit.textContent='Odebírat';} }
    // Hide only the duplicated decorative heading; preserve validation and consent markup.
    const oldTitle=source.querySelector('h1,h2,h3,h4,.newsletter-title');
    if(oldTitle&&!oldTitle.contains(form))oldTitle.classList.add('bema-newsletter-old-title');
    // Preserve native field wrappers, validation, consent and submit behavior.
    const emailGroup=email.closest('.form-group')||email.parentElement;
    const submitGroup=submit?.closest('.form-group')||submit?.parentElement;
    if(emailGroup&&emailGroup!==form&&!emailGroup.contains(submit))emailGroup.classList.add('bema-newsletter-field');
    if(submitGroup&&submitGroup!==form&&!submitGroup.contains(email))submitGroup.classList.add('bema-newsletter-action');
    for(const p of source.querySelectorAll('p')) {
      if(!p.querySelector('a,input,button,select,textarea')&&/vložte svoj e-mail|vložte svůj e-mail|zadejte svůj e-mail/i.test(p.textContent))p.classList.add('bema-newsletter-intro');
    }
    body.append(source);band.append(title,body);grid.before(band);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initNewsletter,{once:true});else initNewsletter();
})();

/* Production capacity ticker — animate once, static final value without JS */
(() => {
  function init() {
    if(!('IntersectionObserver' in window))return;
    const motion=matchMedia('(prefers-reduced-motion: reduce)');
    if(motion.matches)return;
    const format=new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:0});
    const observer=new IntersectionObserver(entries=>{
      for(const entry of entries){
        if(!entry.isIntersecting||entry.intersectionRatio<.5)continue;
        const el=entry.target;observer.unobserve(el);
        const target=Number(el.dataset.bemaProductionCount),final=el.textContent;
        if(!Number.isFinite(target)||target<=0||motion.matches)continue;
        const start=performance.now();
        function tick(now){
          const p=Math.min(1,(now-start)/1100);
          if(p>=1||motion.matches){el.textContent=final;return;}
          el.textContent='≈\u00a0'+format.format(Math.round(target*(1-Math.pow(1-p,4))));
          requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
      }
    },{threshold:.5});
    document.querySelectorAll('.in-index .bema-production [data-bema-production-count]').forEach(el=>observer.observe(el));
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();

/* Category cards — preserve native cart form and refresh after listing updates */
(() => {
  function init() {
    if(!document.body.classList.contains('type-category'))return;
    const enhance=()=>{
      document.querySelectorAll('#products .product .p').forEach(card=>{
        const code=card.querySelector('.p-code'),name=card.querySelector('.p-in-in > .name');
        if(code&&name&&name.nextElementSibling!==code)name.after(code);
        const button=card.querySelector('button.btn-cart');
        if(!button||button.classList.contains('bema-category-bag'))return;
        const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
        svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.8');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');
        const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d','M5 8h14l1 13H4L5 8z M9 9V6a3 3 0 0 1 6 0v3');svg.append(path);button.append(svg);button.classList.add('bema-category-bag');
      });
    };
    enhance();
    document.addEventListener('ShoptetDOMPageContentLoaded',enhance);
    document.addEventListener('ShoptetDOMPageMoreProductsLoaded',enhance);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();

/* Potisk article — local preview and live same-origin category products */
(() => {
 const start=()=>document.querySelectorAll('.bema-print-page').forEach(root=>{
 if(root.dataset.ppReady)return;root.dataset.ppReady='1';
 const q=s=>root.querySelector(s),logo=q('.bema-pp-logo'),file=q('[data-pp-file]'),txt=q('[data-pp-text]'),error=q('[data-pp-error]');let objectURL='';
 function clear(){if(objectURL)URL.revokeObjectURL(objectURL);objectURL='';}
 function textLogo(v){clear();logo.textContent=v||'Vaše značka';}
 txt.addEventListener('input',()=>{file.value='';textLogo(txt.value.trim());});
 q('[data-pp-sample]').addEventListener('click',()=>{file.value='';txt.value='MÝDLO POD LIPOU';textLogo(txt.value);});
 file.addEventListener('change',()=>{const f=file.files[0];if(!f)return;error.textContent='';if(f.size>10485760||!/^image\/(png|jpeg|webp|svg\+xml)$/.test(f.type)){error.textContent='Nepodporovaný soubor nebo velikost nad 10 MB.';return;}clear();objectURL=URL.createObjectURL(f);const img=document.createElement('img');img.alt='Nahrané logo';img.src=objectURL;img.onerror=()=>{error.textContent='Logo se nepodařilo načíst.';textLogo('');};logo.replaceChildren(img);txt.value='';});
 const transform=()=>{logo.style.transform='translate(-50%,-50%) translate('+q('[data-pp-x]').value+'px,'+q('[data-pp-y]').value+'px) rotate('+q('[data-pp-rotation]').value+'deg) scale('+q('[data-pp-size]').value/100+')';};
 root.querySelectorAll('input[type=range]').forEach(e=>e.addEventListener('input',transform));transform();
 const tech=q('[data-pp-tech]'),colors=q('[data-pp-colors]'),qty=q('[data-pp-qty]');
 function quote(){const full=tech.value==='Etiketa na míru',max=tech.value==='Tampotisk'?2:3;colors.disabled=full;[...colors.options].forEach(o=>o.disabled=Number(o.value)>max);if(Number(colors.value)>max)colors.value=String(max);q('[data-pp-quote]').textContent=Number(qty.value)<1000?'Potisk nabízíme od 1 000 ks.': 'Cenu potisku pro '+Number(qty.value).toLocaleString('cs-CZ')+' ks potvrdíme v nabídce.';}
 [tech,colors,qty].forEach(e=>e.addEventListener('input',quote));quote();
 const strip=q('[data-product-source]'),track=q('.bema-pp-track'),status=q('[data-pp-status]'),prev=q('[data-pp-prev]'),next=q('[data-pp-next]');
 function sync(){prev.disabled=track.scrollLeft<2;next.disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-2;}
 function step(dir){const card=track.firstElementChild;if(card)track.scrollBy({left:dir*(card.getBoundingClientRect().width+16),behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}
 prev.addEventListener('click',()=>step(-1));next.addEventListener('click',()=>step(1));track.addEventListener('scroll',sync,{passive:true});if('ResizeObserver'in window)new ResizeObserver(sync).observe(track);
 async function load(){status.textContent='Načítání produktů…';try{const url=new URL(strip.dataset.productSource,location.origin);if(url.origin!==location.origin)throw Error('origin');const res=await fetch(url,{credentials:'same-origin'});if(!res.ok)throw Error('HTTP');const doc=new DOMParser().parseFromString(await res.text(),'text/html');const cards=[...doc.querySelectorAll('#products .product .p')].slice(0,Math.min(24,Math.max(1,Number(strip.dataset.productLimit)||8)));for(const p of cards){const n=p.querySelector('.name'),im=p.querySelector('.image img');if(!n||!im)continue;const href=new URL(n.getAttribute('href'),url);if(href.origin!==location.origin)continue;const src=new URL(im.getAttribute('data-src')||im.getAttribute('src'),url);if(!/^https?:$/.test(src.protocol))continue;const link=document.createElement('a');link.className='bema-pp-card';link.href=href.href;const image=document.createElement('img');image.src=src.href;image.alt='';image.loading='lazy';image.width=280;image.height=280;const name=document.createElement('strong');name.textContent=n.textContent.trim();link.append(image,name);for(const [sel,cls] of [['.availability',''],['.price-final','bema-pp-card-price']]){const v=p.querySelector(sel);if(v){const t=document.createElement('span');t.className=cls;t.textContent=v.textContent.trim();link.append(t);}}track.append(link);q('[data-pp-pack]').add(new Option(name.textContent,href.href));}status.textContent=track.children.length?'':'Produkty najdete v katalogu.';sync();}catch{status.textContent='Produkty se nepodařilo načíst. Přejděte do katalogu.';}}
 if('IntersectionObserver'in window){const ob=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)){ob.disconnect();load();}},{rootMargin:'400px'});ob.observe(root.querySelector('#configurator'));}else load();
 q('[data-pp-pack]').addEventListener('change',()=>{const v=q('[data-pp-pack]').value;const card=[...track.children].find(c=>c.href===v);if(card){q('.bema-pp-bottle').title='Ilustrační náhled: '+card.querySelector('strong').textContent;}});
 });if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();

/* Samples page — category-backed picker; draft request only until a real endpoint is connected */
(() => {
const sources=[['/lahve/','Lahve'],['/uzavery-a-vicka/','Uzávěry'],['/pumpicky-a-rozprasovace/','Pumpičky a rozprašovače'],['/dozy-a-kelimky/','Dózy'],['/kanystry/','Kanystry'],['/kbeliky/','Kbelíky']];
const formMarkup='<form class="bema-sp-form"><label>IČO<input name="ico" required inputmode="numeric" pattern="[0-9]{8}" maxlength="8"></label><label>Název firmy<input name="company" required autocomplete="organization"></label><label>Země<select name="country"><option>Česká republika</option><option>Slovensko</option><option>Jiná</option></select></label><label>Ulice a číslo<input name="street" required autocomplete="street-address"></label><label>PSČ<input name="zip" required autocomplete="postal-code"></label><label>Město<input name="city" required autocomplete="address-level2"></label><label>Jméno a příjmení<input name="contact" required autocomplete="name"></label><label>E-mail<input name="email" type="email" required autocomplete="email"></label><label>Telefon<input name="phone" type="tel" required autocomplete="tel"></label><label>Na jaký produkt obal hledáte<select name="sector"><option value="">Vyberte obor</option><option>Drogerie a chemie</option><option>Potravinářství a nápoje</option><option>Kosmetika a wellness</option><option>Farmacie a zdravotnictví</option><option>Zahrada a domácnost</option><option>Průmysl a chemikálie</option></select></label><label>Poznámka<textarea name="note" rows="3"></textarea></label><label class="bema-sp-consent"><input type="checkbox" required name="consent"><span>Souhlasím se zpracováním osobních údajů pro odeslání vzorků a s <a href="/obchodni-podminky/">obchodními podmínkami</a>.</span></label><button type="submit" class="bema-sp-submit" disabled>Připravit žádost o vzorky</button><p class="bema-sp-message" role="status">Testovací verze: žádost se zatím neodesílá.</p></form>';
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function init(root){
if(root.dataset.bemaSpReady)return;root.dataset.bemaSpReady='1';
const q=s=>root.querySelector(s),slots=q('.bema-sp-slots'),results=q('.bema-sp-results'),search=q('.bema-sp-search'),status=q('.bema-sp-status'),chips=q('.bema-sp-chips'),card=q('.bema-sp-form-card');
if(!slots||!results||!search||!status||!chips||!card||!q('.bema-sp-form-mount'))return;
q('.bema-sp-form-mount').innerHTML=formMarkup;const form=q('.bema-sp-form'),submit=q('.bema-sp-submit');
const selected=new Map(),cache=new Map();let active=0,products=[],seq=0;
const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e;};
const pic=p=>{const im=make('img');im.src=p.image;im.alt='';im.loading='lazy';im.width=64;im.height=64;return im;};
const mobile=make('div','bema-sp-mobile');mobile.hidden=true;const mobileCount=make('span'),go=make('button','','Pokračovat k údajům');go.type='button';go.addEventListener('click',()=>card.scrollIntoView({block:'start'}));mobile.append(mobileCount,go);root.append(mobile);
function render(){
q('.bema-sp-count').textContent=selected.size+' z 5';mobileCount.textContent='Vzorky: '+selected.size+' z 5';mobile.hidden=!selected.size;submit.disabled=!selected.size;
slots.replaceChildren();const items=[...selected.values()];for(let i=0;i<5;i++){const box=make('div','bema-sp-slot'),p=items[i];if(p){const b=make('button','bema-sp-remove','×');b.type='button';b.setAttribute('aria-label','Odebrat '+p.name);b.addEventListener('click',()=>{selected.delete(p.url);render();});box.append(pic(p),make('span','',p.name),b);}else{const b=make('button','','+ Přidat vzorek');b.type='button';b.addEventListener('click',()=>search.focus());box.append(b);}slots.append(box);}
results.replaceChildren();const filtered=products.filter(p=>norm(p.name+' '+p.code).includes(norm(search.value.trim()))).slice(0,8);
for(const p of filtered){const row=make('div','bema-sp-row'),copy=make('div'),link=make('a');link.href=p.url;link.append(make('strong','',p.name));copy.append(link,make('small','',p.code));const on=selected.has(p.url),b=make('button','bema-sp-add',on?'Vybráno':'Přidat');b.type='button';b.setAttribute('aria-pressed',String(on));b.disabled=!on&&selected.size>=5;b.addEventListener('click',()=>{if(selected.has(p.url))selected.delete(p.url);else if(selected.size<5)selected.set(p.url,p);render();});row.append(pic(p),copy,b);results.append(row);}
status.textContent=filtered.length?(selected.size===5?'Máte vybráno 5 vzorků.':''):'V načtených produktech nebyla nalezena shoda.';
}
async function load(i){active=i;const token=++seq;chips.querySelectorAll('button').forEach((b,k)=>b.setAttribute('aria-pressed',String(k===i)));status.textContent='Načítání produktů…';products=[];results.replaceChildren();try{if(!cache.has(i)){const url=new URL(sources[i][0],location.origin),res=await fetch(url,{credentials:'same-origin'});if(!res.ok)throw Error('HTTP');const doc=new DOMParser().parseFromString(await res.text(),'text/html'),items=[];for(const p of doc.querySelectorAll('#products .product .p')){const n=p.querySelector('.name'),im=p.querySelector('.image img');if(!n||!im||!n.getAttribute('href'))continue;const href=new URL(n.getAttribute('href'),url),raw=im.getAttribute('data-src')||im.getAttribute('src');if(!raw)continue;const image=new URL(raw,url);if(href.origin!==location.origin||!/^https?:$/.test(image.protocol))continue;items.push({name:n.textContent.trim(),code:p.querySelector('.p-code')?.textContent.trim()||'',url:href.href,image:image.href});}cache.set(i,items);}if(token!==seq)return;products=cache.get(i);render();}catch{if(token===seq)status.textContent='Kategorii se nepodařilo načíst.';}}
sources.forEach((s,i)=>{const b=make('button','',s[1]);b.type='button';b.addEventListener('click',()=>load(i));chips.append(b);});search.addEventListener('input',()=>{if(cache.has(active))render();});
form.addEventListener('submit',e=>{e.preventDefault();if(!selected.size||!form.reportValidity())return;q('.bema-sp-message').textContent='Údaje jsou vyplněny. Testovací verze žádost neodesílá; odesílání bude aktivováno po napojení formuláře.';});
if('ResizeObserver'in window)new ResizeObserver(()=>{card.style.setProperty('--bema-sp-top',Math.min(120,window.innerHeight-card.offsetHeight-24)+'px');}).observe(card);
render();load(0);
}
const start=()=>document.querySelectorAll('.bema-samples-page').forEach(init);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
